const e={title:"TripReel - Aplicație Gratuită de Animație Călătorii: Transformă Pozele în Videoclipuri Estetice",description:"Creează videoclipuri uimitoare de călătorie cu hărți animate și trasee de zbor. Aplicație gratuită de animație călătorii cu cartografiere rută glob 3D. Transformă pozele tale în videoclipuri estetice de călătorie automat. Confidențialitate mai întâi, funcționează offline.",keywords:"aplicație animație călătorii, aplicație animație hartă călătorii, aplicație animație rută călătorii, aplicație animație zbor, creator video călătorii, video călătorie automat, hartă călătorie animată, animație traseu zbor, animație călătorie, animație glob, video recapitulare călătorie, poză în video, evidențiere călătorie, aplicație călătorie gratuită, creator video offline, aplicație călătorie confidențială, video rolă cameră"},i={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Cum Funcționează",video:"Video",features:"Funcționalități",theApp:"Aplicația"},a={badge:"Transformă Pozele în Povești de Călătorie",title1:"Galeria Ta Foto,",title2:"În Prim-Plan",description:"TripReel creează automat videoclipuri estetice de călătorie din locațiile pozelor tale. Urmărește cum călătoriile tale prind viață cu hărți de rută animate și trasee de zbor pe un glob 3D, în timp ce datele tale rămân private și sigure.",secure:"100% Sigur",worksOffline:"Funcționează Offline",globeAlt:"Animație Glob TripReel"},t={title:"Cum Funcționează",subtitle:"Trei pași simpli pentru a crea videoclipul tău perfect",step1:{title:"Acordă Acces la Poze",description:"Permite TripReel să acceseze galeria foto. Aplicația citește doar metadatele de locație, nimic altceva."},step2:{title:"Detectare Automată a Călătoriilor",description:"TripReel analizează metadatele de locație și identifică inteligent călătoriile tale în funcție de date și locații."},step3:{title:"Generează Videoclipul",description:"Privește cum călătoria ta se desfășoară pe o animație estetică pe glob, gata să fie partajată pe rețelele sociale."}},r={title:"Vezi Magia în Acțiune",subtitle:"Descoperă cum TripReel transformă galeria ta foto în videoclipuri de călătorie uimitoare",caption:"Așa va arăta videoclipul tău final de călătorie"},o={title:"Tot Ce Ai Nevoie",subtitle:"Funcționalități puternice proiectate pentru călătorii moderni",twoTap:{title:"Video în Două Atingeri",description:"Creează videoclipuri uimitoare din galeria foto în doar două atingeri. Fără editare necesară."},smartTrip:{title:"Detectare Inteligentă",description:"Găsește și grupează automat călătoriile tale analizând datele și metadatele de locație din poze."},globe:{title:"Animație estetică pe Glob",description:"Privește cum călătoria ta prinde viață cu un glob 3D uimitor care arată rutele tale animate și traseele de zbor din întreaga lume."},privacy:{title:"Confidențialitate Mai Întâi",description:"Totul se procesează pe dispozitivul tău. Pozele tale nu părăsesc niciodată telefonul. Funcționează în modul avion."},customStyles:{title:"Stiluri Personalizabile",description:"Alege dintre mai multe stiluri de glob și personalizări pentru a se potrivi esteticii tale și a face fiecare video unic."},manualControl:{title:"Control Manual",description:"Poți adăuga manual călătorii noi dacă serviciile de locație nu erau activate pe dispozitiv."}},l={title:"Idei Creative de Video",subtitle:"Inspiră-te cu ceea ce poți crea folosind TripReel. De la scurte călătorii de weekend până la aventuri de un an, creează videoclipuri uimitoare pentru fiecare călătorie.",description:"Fie că creezi o animație de hartă de călătorie, documentezi o rută de zbor sau faci o recapitulare anuală de călătorii, TripReel face ușor să transformi amintirile tale în videoclipuri care pot fi partajate.",ideas:{yearRecap:{title:"Recapitulare 2025",description:"Creează automat videoclipul cu călătoriile din 2025"},europeRoadTrip:{title:"Tur Europa cu Mașina",description:"Prezintă aventura ta europeană cu hărți de rută animate"},southeastAsia:{title:"Călătorie Asia de Sud-Est",description:"Vizualizează traseul tău prin mai multe țări"},japanRail:{title:"Călătorie Tren în Japonia",description:"Creează video-uri cu rutele tale de tren prin Japonia"},crossCountry:{title:"Traversare SUA",description:"Transformă turul tău american într-un video epic de rută"},islandHopping:{title:"Tururi pe Insule",description:"Arată călătoriile tale din insulă în insulă cu animații 3D uimitoare"},worldTour:{title:"Tur Mondial Montaj",description:"Mai multe călătorii într-un singur video global uimitor"},travelPlans:{title:"Planuri de Călătorie 2026",description:"Vizualizează și planifică aventurile tale din 2026"},lifetimeTravel:{title:"Poveste de Călătorie",description:"Creează un video cu toate călătoriile tale din viață"},regionalExplorer:{title:"Explorator Regional",description:"Trasează aventurile tale prin state, provincii și regiuni"},festivalCircuit:{title:"Circuit de Festivaluri",description:"Mapează călătoria ta prin festivaluri de muzică și evenimente"},bikeRoutes:{title:"City Break-urile Mele",description:"Prezintă toate escapadele tale urbane"}}},n={title:"Aplicația",subtitle:"Disponibilă acum pe App Store",alt1:"Video-uri Automate de Călătorie - Creează video-uri uimitoare în câteva secunde",alt2:"Detectare Locație din Poze - Folosește metadatele pozelor tale",alt3:"Detectare Călătorii - Grupează automat călătoriile tale",alt4:"Video-uri Estetice Glob - Animație glob a călătoriei tale",alt5:"Stiluri Personalizate - Personalizează video-urile tale de călătorie"},c={comingSoon:"În Curând",androidTitle:"Aplicația Android În Curând!",androidMessage:'Versiunea Android nu este încă disponibilă, dar va fi în curând. Trimite-mi un mesaj la <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> și te voi anunța când va fi gata!',gotIt:"Am înțeles!"},u={title:"Întrebări Frecvente",subtitle:"Tot ce trebuie să știi despre TripReel",q1:{question:"Pot folosi aplicația complet în modul avion?",answer:"Da! Pentru utilizatorii premium, aplicația poate fi folosită complet offline în modul avion, fără limitări. Pentru utilizatorii non-premium, unele funcționalități sunt susținute de reclame care ar putea necesita activarea temporară a internetului, dar pentru utilizatorii premium nu există reclame și aplicația poate fi folosită complet în modul avion."},q2:{question:"Am făcut upgrade la Premium, cum pot elimina watermark-ul?",answer:"Mulți oameni întreabă ce aplicație a fost folosită pentru a crea aceste video-uri, așa că, după upgrade la premium, ai opțiunea de a adăuga o versiune mai mică a watermark-ului (doar cu numele aplicației) sau să îl elimini complet dacă dorești."},q3:{question:"Sunt datele mele foto sigure și private?",answer:"Absolut! TripReel citește doar metadatele de locație din pozele tale - nu accesăm, stocăm sau transmitem niciodată conținutul real al pozelor. Toată procesarea se întâmplă local pe dispozitivul tău, și nicio dată nu părăsește telefonul tău. Poți verifica acest lucru folosind aplicația în modul avion - funcționează perfect offline!"},q4:{question:"Ce fac dacă pozele mele nu au date de locație?",answer:"Nicio problemă! Dacă serviciile de locație nu erau activate când ai făcut pozele, poți crea manual călătorii și adăuga locații singur. Aplicația îți oferă control complet pentru a personaliza cronologia călătoriilor tale."},q5:{question:"Cum detectează aplicația călătoriile mele automat?",answer:"TripReel analizează metadatele de locație și marcajele de timp din pozele tale pentru a identifica inteligent când și unde ai călătorit. Grupează locațiile și datele apropiate pentru a detecta automat călătoriile tale fără nicio muncă manuală."},q6:{question:"Pot personaliza aspectul video-urilor mele?",answer:"Da! Poți alege dintre mai multe stiluri de glob și personaliza diverse aspecte ale video-urilor tale animate de călătorie pentru a se potrivi esteticii tale personale. Utilizatorii premium au acces la stiluri suplimentare de animație a rutelor, teme de hartă și opțiuni de trasee de zbor."},q7:{question:"Trebuie să creez un cont?",answer:"Nu este necesar niciun cont! TripReel funcționează imediat după descărcare. Nu există înregistrare, nu există autentificare și nu sunt necesare informații personale. Doar descarcă aplicația și începe să creezi video-urile tale de călătorie imediat."},q8:{question:"De ce lipsește o locație din călătoria mea?",answer:"Aplicația poate funcționa doar cu datele disponibile, așa că mai întâi de toate ai nevoie de cel puțin câteva poze în acea locație. În al doilea rând, trebuie să te asiguri că aveai datele de locație activate când erai acolo. În al treilea rând, uneori recepția GPS slabă poate cauza date de locație greșite. Dacă ai exclus toate acestea și locația ta încă nu apare, poți adăuga manual acea locație din Trips Overview > butonul Edit. Te rog folosește Contact pentru a raporta problema."},q9:{question:"Unde pot partaja video-ul meu?",answer:"Desigur, poți să îl partajezi și pe toate platformele sociale. Pentru a se potrivi mai bine platformei, aplicația permite diferite rapoarte de aspect pentru video-urile tale."},q10:{question:"Unde pot raporta un bug?",answer:"Doar contactează-mă direct la marian@qod.ee, explicând pe scurt care este problema."}},d={title:"Suport Email",description:"Dacă ai orice feedback sau întâmpini probleme, te rog să mă contactezi direct la acest email și voi citi și gestiona personal cererea ta cât mai repede posibil. Mulțumesc că folosești aplicația!",close:"Închide"},p={default:{title:"🍪 Cookie-uri",message:"Folosim cookie-uri pe site-ul TripReel pentru a îmbunătăți experiența ta. Nu sunt colectate date personale.",accept:"Acceptă",decline:"Refuză",details:"Detalii"},theme:{title:"🍪 Cookie-uri",message:"🌙 Pentru a salva preferința ta de temă, trebuie să accepți cookie-urile esențiale pe site-ul TripReel. Fără ele, alegerea ta de temă nu poate fi salvată.",accept:"Acceptă",decline:"Refuză",details:"Detalii"}},s={privacy:"Politica de Confidențialitate",cookies:"Politica de Cookie-uri Site",contact:"Contact",cookiePreferences:"Preferințe Cookie-uri",madeWith:"Creat cu",forTravelers:"pentru călătorii din întreaga lume",copyright:"© {{year}} TripReel."},m={title:"Gata să Împărtășești Călătoria Ta?",description:"Descarcă TripReel astăzi și transformă galeria foto în videoclipuri estetice de călătorie cu hărți și rute animate. Aventurile tale merită să fie celebrate.",features:"Gratuit de descărcat • Rapid & Convenabil • Confidențialitate garantată"},v={meta:e,header:i,hero:a,howItWorks:t,videoSection:r,features:o,videoIdeas:l,screenshots:n,appStore:c,faq:u,contact:d,cookieBanner:p,footer:s,cta:m};export{c as appStore,d as contact,p as cookieBanner,m as cta,v as default,u as faq,o as features,s as footer,i as header,a as hero,t as howItWorks,e as meta,n as screenshots,l as videoIdeas,r as videoSection};
